import os, sys, urllib.request, urllib.parse, gzip, base64

_DATA_EMBEDDED = {
    "quartets.csv": "",
    "StudentsPerformance.csv": "",
}

def load_dataset(filename, module_name="04 - EDA"):
    candidates = [
        os.path.join("data", filename),
        os.path.join(module_name, "data", filename),
        os.path.join("Data Science programming", module_name, "data", filename),
        os.path.join("..", "data", filename),
        os.path.join("..", module_name, "data", filename),
        filename
    ]
    for path in candidates:
        if os.path.exists(path):
            return path
            
    os.makedirs("data", exist_ok=True)
    target_path = os.path.join("data", filename)
    encoded_module = urllib.parse.quote(f"Data Science programming/{module_name}")
    encoded_file = urllib.parse.quote(filename)
    url_main = f"https://raw.githubusercontent.com/sazuniga06/Data-Science-Programming---USTA-Tunja-Repository/main/{encoded_module}/data/{encoded_file}"
    url_master = f"https://raw.githubusercontent.com/sazuniga06/Data-Science-Programming---USTA-Tunja-Repository/master/{encoded_module}/data/{encoded_file}"
    
    print(f"📥 Descargando dataset '{filename}' desde el repositorio oficial...")
    try:
        urllib.request.urlretrieve(url_main, target_path)
        print(f"✅ Dataset '{filename}' cargado exitosamente.")
        return target_path
    except Exception:
        pass
        
    try:
        urllib.request.urlretrieve(url_master, target_path)
        print(f"✅ Dataset '{filename}' cargado exitosamente.")
        return target_path
    except Exception:
        pass
        
    if filename in _DATA_EMBEDDED:
        raw = gzip.decompress(base64.b64decode(_DATA_EMBEDDED[filename]))
        with open(target_path, "wb") as f:
            f.write(raw)
        print(f"✅ Dataset '{filename}' restaurado desde respaldo embebido.")
        return target_path
        
    raise FileNotFoundError(f"No se pudo cargar '{filename}'")
